// The JS selector engine (src/runtime/selectors.mjs) against the Chrome 156 control that
// also gates the Rust engine: crates/turbo-dom/tests/fixtures/cascade_selectors_chrome156.json
// (generated by scripts/cascade-selectors-chrome-control.mjs; miaskiewicz/turbo-dom#18).
// For every case and selector: validity (querySelector throws exactly where Chrome does),
// `matches` for every element, `querySelectorAll`, and the partial cascade (cascade.mjs)
// applying the sentinel `SEL { order: 1 }` rule exactly where Chrome's computed `order` is 1.
// The scripted probes (template content traversal, `:root` outside the document element)
// are replayed through the same DOM calls.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createEnvironment } from '../src/runtime/index.mjs';

const fixture = JSON.parse(
  readFileSync(new URL('../crates/turbo-dom/tests/fixtures/cascade_selectors_chrome156.json', import.meta.url), 'utf8'),
);

// Elements in document order (Chrome walks `children`; template content is excluded).
function elements(document) {
  const out = [];
  const walk = (el) => { out.push(el); for (const c of el.children) walk(c); };
  walk(document.documentElement);
  return out;
}

const throws = (fn) => { try { fn(); return false; } catch (e) { assert.ok(e instanceof SyntaxError, String(e)); return true; } };

test('selector engine matches the Chrome 156 control (validity, matches, querySelectorAll)', () => {
  assert.ok(fixture.chrome.startsWith('156.'));
  const failures = [];
  let rows = 0;
  for (const c of fixture.cases) {
    const { document } = createEnvironment(c.html);
    const els = elements(document);
    assert.deepEqual(els.map((e) => e.localName), c.elements, `${c.id}: element list`);
    for (const r of c.selectors) {
      rows++;
      const fail = (what) => failures.push(`${c.id} \`${r.selector}\`: ${what}`);
      if (throws(() => document.querySelector(r.selector)) === r.valid) fail(`validity, Chrome valid=${r.valid}`);
      if (!r.valid) {
        if (!throws(() => els[0].matches(r.selector))) fail('matches accepted an invalid selector');
        continue;
      }
      const got = els.map((e) => (e.matches(r.selector) ? '1' : '0')).join('');
      if (got !== r.matches) fail(`matches ${got}, Chrome ${r.matches}`);
      const qsa = [...document.querySelectorAll(r.selector)].map((e) => els.indexOf(e));
      if (JSON.stringify(qsa) !== JSON.stringify(r.qsa)) fail(`querySelectorAll ${qsa}, Chrome ${r.qsa}`);
      const first = document.querySelector(r.selector);
      if ((first ? els.indexOf(first) : undefined) !== r.qsa[0]) fail('querySelector');
    }
  }
  assert.ok(rows > 250, `fixture shrank: ${rows} rows`);
  assert.deepEqual(failures, []);
});

test('partial cascade applies the sentinel rule exactly where Chrome does', () => {
  const failures = [];
  for (const c of fixture.cases) {
    for (const r of c.selectors) {
      const html = c.html.replace('</head>', `<style>${r.selector} { order: 1 }</style></head>`);
      const { window, document } = createEnvironment(html);
      const els = elements(document).filter((e) => e !== document.head.lastElementChild);
      const got = els.map((e) => (window.getComputedStyle(e).order === '1' ? '1' : '0')).join('');
      if (got !== r.winner) failures.push(`${c.id} \`${r.selector}\`: cascade ${got}, Chrome ${r.winner}`);
    }
  }
  assert.deepEqual(failures, []);
});

// miaskiewicz/turbo-dom#24 item 2: the partial cascade ranks rules by Selectors 4 specificity
// (then source order), so every cascade case but the layout cascade's `cascade-order` ones
// (importance, origins) resolves Chrome's winning `order`.
test('partial cascade picks Chrome\'s winner in every specificity / validity cascade case', () => {
  const failures = [];
  let cases = 0;
  for (const c of fixture.cascade_cases) {
    if (c.class === 'cascade-order') continue;
    cases++;
    const html = c.html.replace('</head>', `<style>${c.css}</style></head>`);
    const { window, document } = createEnvironment(html);
    const els = elements(document).filter((e) => e !== document.head.lastElementChild);
    const got = els.map((e) => window.getComputedStyle(e).order || '0');
    if (JSON.stringify(got) !== JSON.stringify(c.winners)) failures.push(`${c.id}: ${got}, Chrome ${c.winners}`);
  }
  assert.ok(cases >= 8, `cascade cases shrank: ${cases}`);
  assert.deepEqual(failures, []);
});

test('scripted probes: template content traversal and :root', () => {
  const probes = Object.fromEntries(fixture.probes.map((p) => [p.id, p]));
  {
    const { html, values } = probes['template-traversal'];
    const { document } = createEnvironment(html);
    const t = document.getElementById('t');
    const inner = t.content.querySelector('p');
    assert.deepEqual({
      by_id_in_content: document.getElementById('in') === null ? 'null' : 'found',
      by_tag_span: document.getElementsByTagName('span').length,
      by_tag_p: document.getElementsByTagName('p').length,
      qsa_from_template: t.querySelectorAll('p').length,
      qsa_from_content: t.content.querySelectorAll('p').length,
      content_p_matches_template_p: inner.matches('template p'),
      content_p_matches_root: inner.matches(':root'),
      content_p_matches_first_child: inner.matches(':first-child'),
      content_span_matches_div_span: t.content.querySelector('span').matches('div span'),
      template_matches_has_p: t.matches(':has(p)'),
      template_matches_empty: t.matches(':empty'),
    }, values);
  }
  {
    const { html, values } = probes.root;
    const { document } = createEnvironment(html);
    const detached = document.createElement('div');
    detached.append(document.createElement('span'));
    const fragment = document.createDocumentFragment();
    fragment.append(document.createElement('p'));
    const shadow = document.getElementById('host').attachShadow({ mode: 'open' });
    shadow.innerHTML = '<p>s</p>';
    const template = document.createElement('template');
    template.innerHTML = '<p>t</p>';
    const templateChild = (template.content && template.content.firstChild) || template.firstChild;
    assert.deepEqual({
      document_element: document.documentElement.matches(':root'),
      body: document.body.matches(':root'),
      qsa_root: document.querySelectorAll(':root').length,
      detached: detached.matches(':root'),
      detached_child: detached.firstChild.matches(':root'),
      fragment_child: fragment.firstChild.matches(':root'),
      shadow_child: shadow.firstChild.matches(':root'),
      template_content_child: templateChild.matches(':root'),
      fragment_qsa_root: fragment.querySelectorAll(':root').length,
      root_child_combinator: document.body.matches(':root > body'),
    }, values);
  }
});
